8: const MapDefaultCamera = ({ filteredPositions }) => {
9:   const selectedDeviceId = useSelector((state) => state.devices.selectedId);
10:   const positions = useSelector((state) => state.session.positions);
11: 
12:   const defaultLatitude = usePreference('latitude');
13:   const defaultLongitude = usePreference('longitude');
14:   const defaultZoom = usePreference('zoom', 0);
15: 
16:   const [initialized, setInitialized] = useState(false);
17: 
18:   useEffect(() => {
19:     if (initialized) return;
20:     if (selectedDeviceId) {
21:       const position = positions[selectedDeviceId];
22:       if (position) {
23:         map.jumpTo({
24:           center: toMapCoordinates(position.longitude, position.latitude),
25:           zoom: Math.max(defaultZoom > 0 ? defaultZoom : map.getZoom(), 10),
26:         });
27:         setInitialized(true);
28:       }
29:     } else {
30:       if (defaultLatitude && defaultLongitude) {
31:         map.jumpTo({
32:           center: toMapCoordinates(defaultLongitude, defaultLatitude),
33:           zoom: defaultZoom,
34:         });
35:         setInitialized(true);
36:       } else {
37:         const coordinates = (filteredPositions || Object.values(positions)).map((item) =>
38:           toMapCoordinates(item.longitude, item.latitude),
39:         );
40:         if (coordinates.length > 1) {
41:           const bounds = coordinates.reduce(
42:             (bounds, item) => bounds.extend(item),
43:             new maplibregl.LngLatBounds(coordinates[0], coordinates[1]),
44:           );
45:           const canvas = map.getCanvas();
46:           map.fitBounds(bounds, {
47:             duration: 0,
48:             padding: Math.min(canvas.width, canvas.height) * 0.1,
49:           });
50:           setInitialized(true);
51:         } else if (coordinates.length) {
52:           const [individual] = coordinates;
53:           map.jumpTo({
54:             center: individual,
55:             zoom: Math.max(defaultZoom > 0 ? defaultZoom : map.getZoom(), 10),
56:           });
57:           setInitialized(true);
58:         }
59:       }
60:     }
61:   }, [
62:     selectedDeviceId,
63:     initialized,
64:     defaultLatitude,
65:     defaultLongitude,
66:     defaultZoom,
67:     positions,
68:     filteredPositions,
69:   ]);
70: 
71:   return null;
72: };
